properties.query:
//detects the use of fodhelper to bypass UAC
//Attackers use this to escalate privileges
let UAC_Bypass_Fodhelper_1 =
SecurityEvent
| where CommandLine has_any ("New-ItemProperty","Set-ItemProperty")
| where CommandLine has @"\Software\Classes\ms-settings\Shell\Open\command"
| where CommandLine has_any ("DelegateExecute","(default)")
| project Computer, BB1_Time = TimeGenerated, BB1_Command = CommandLine;
let UAC_Bypass_Fodhelper_2 =
SecurityEvent
| where CommandLine has "C:\\Windows\\System32\\fodhelper.exe"
| project Computer, BB2_Time = TimeGenerated, BB2_Command = CommandLine;
UAC_Bypass_Fodhelper_1
| join kind=inner (UAC_Bypass_Fodhelper_2) on Computer
| where BB2_Time between (BB1_Time .. BB1_Time + 1m)
| project Computer, BB1_Time, BB1_Command, BB2_Time, BB2_Command
| sort by BB1_Time desc
| extend
    ComputerName = tostring(column_ifexists("Computer", "")),
    Account = tostring(
        coalesce(
            column_ifexists("SubjectUserName", ""),
            column_ifexists("Account", "")
        )
    ),
    CommandLineMapped = tostring(column_ifexists("ServiceFileName", ""))
